import { readFileSync } from 'node:fs';

import type { ContentBlock, TranscriptEntry } from './types.js';

/** Nanoseconds per millisecond. */
export const NANOSECONDS_PER_MS = 1e6;
/** Nanoseconds per second. */
export const NANOSECONDS_PER_S = 1e9;

/**
 * Read a Claude Code JSONL transcript and return one `TranscriptEntry` per
 * non-empty line, in file order.
 */
export function readTranscript(filePath: string): TranscriptEntry[] {
  const content = readFileSync(filePath, 'utf-8');
  return content
    .split('\n')
    .filter((line) => line.trim())
    .map((line) => JSON.parse(line) as TranscriptEntry);
}

/**
 * Convert a timestamp to nanoseconds since the Unix epoch.
 *
 * - `null`, `undefined`, and the empty string return `null`.
 * - ISO date strings are parsed via `Date`; unparseable strings return `null`.
 * - Numeric values are interpreted by magnitude: `>= 1e13` are already
 *   nanoseconds, `>= 1e10` are milliseconds, and anything smaller is Unix
 *   seconds. Each is floored after scaling.
 */
export function parseTimestampToNs(ts: string | number | null | undefined): number | null {
  if (ts === null || ts === undefined || ts === '') {
    return null;
  }

  if (typeof ts === 'number') {
    if (!isFinite(ts)) {
      return null;
    }
    if (ts >= 1e13) {
      return Math.floor(ts);
    }
    if (ts >= 1e10) {
      return Math.floor(ts * NANOSECONDS_PER_MS);
    }
    return Math.floor(ts * NANOSECONDS_PER_S);
  }

  const ms = new Date(ts).getTime();
  if (isNaN(ms)) {
    return null;
  }
  return Math.floor(ms * NANOSECONDS_PER_MS);
}

/**
 * Extract rendered plain text from a message `content` value. Strings are
 * returned unchanged. For an array of content blocks, the `text` fields of
 * all `text` blocks are joined with newlines. An empty array returns `''`.
 */
export function extractTextContent(
  content: string | Array<{ type: string; text?: string; [key: string]: unknown }>,
): string {
  if (typeof content === 'string') {
    return content;
  }
  if (Array.isArray(content)) {
    return content
      .filter((block) => block.type === 'text')
      .map((block) => block.text ?? '')
      .join('\n');
  }
  return '';
}

/** Whether a `user` entry's content is an array of `tool_result` blocks. */
function isToolResultCarrier(entry: TranscriptEntry): boolean {
  const content = entry.message?.content;
  return (
    Array.isArray(content) && content.some((block) => (block as ContentBlock).type === 'tool_result')
  );
}

/**
 * Whether a `user` entry represents a "real" user turn — i.e. not a tool
 * result carrier, not a compaction summary, and not a skill-injection
 * message (whose text starts with `Base directory:`).
 */
export function isRealUserMessage(entry: TranscriptEntry): boolean {
  if (entry.type !== 'user' || !entry.message) {
    return false;
  }
  if (entry.isCompactSummary === true) {
    return false;
  }
  if (isToolResultCarrier(entry)) {
    return false;
  }
  const text = extractTextContent(entry.message.content);
  if (text.startsWith('Base directory:')) {
    return false;
  }
  return true;
}

/**
 * Find the index of the last "real" user message in the transcript, or
 * `null` if there is none (including for an empty array).
 */
export function findLastUserMessageIndex(entries: TranscriptEntry[]): number | null {
  for (let i = entries.length - 1; i >= 0; i--) {
    if (isRealUserMessage(entries[i])) {
      return i;
    }
  }
  return null;
}

/**
 * Find the index of the first "real" user message, or `null` if there is
 * none.
 */
export function findFirstUserMessageIndex(entries: TranscriptEntry[]): number | null {
  for (let i = 0; i < entries.length; i++) {
    if (isRealUserMessage(entries[i])) {
      return i;
    }
  }
  return null;
}

/**
 * Search from `startIndex` onward and return the extracted text of the last
 * assistant entry that has text content, or `null` if none exists.
 */
export function findFinalAssistantResponse(
  entries: TranscriptEntry[],
  startIndex: number,
): string | null {
  let response: string | null = null;
  for (let i = Math.max(0, startIndex); i < entries.length; i++) {
    const entry = entries[i];
    if (entry.type !== 'assistant' || !entry.message) {
      continue;
    }
    const text = extractTextContent(entry.message.content);
    if (text) {
      response = text;
    }
  }
  return response;
}
