AAW,EAAE,IAAI;oBACjB,OAAO,EAAE,KAAK,CAAC,aAAa,EAAE,OAAO;iBACtC,CAAC,CAAC;YACL,CAAC;QACH,CAAC;IACH,CAAC;IACD,OAAO,GAAG,CAAC;AACb,CAAC;AAED,4DAA4D;AAC5D,SAAS,qBAAqB,CAAC,OAA0B;IACvD,MAAM,GAAG,GAAG,IAAI,GAAG,EAA6B,CAAC;IACjD,KAAK,MAAM,KAAK,IAAI,OAAO,EAAE,CAAC;QAC5B,IAAI,KAAK,CAAC,IAAI,KAAK,UAAU,IAAI,KAAK,CAAC,eAAe,EAAE,CAAC;YACvD,MAAM,IAAI,GAAG,GAAG,CAAC,GAAG,CAAC,KAAK,CAAC,eAAe,CAAC,CAAC;YAC5C,IAAI,IAAI,EAAE,CAAC;gBACT,IAAI,CAAC,IAAI,CAAC,KAAK,CAAC,CAAC;YACnB,CAAC;iBAAM,CAAC;gBACN,GAAG,CAAC,GAAG,CAAC,KAAK,CAAC,eAAe,EAAE,CAAC,KAAK,CAAC,CAAC,CAAC;YAC1C,CAAC;QACH,CAAC;IACH,CAAC;IACD,OAAO,GAAG,CAAC;AACb,CAAC;AAED,4DAA4D;AAC5D,SAAS,oBAAoB,CAAC,OAA4C;IACxE,IAAI,OAAO,IAAI,IAAI,EAAE,CAAC;QACpB,OAAO,EAAE,CAAC;IACZ,CAAC;IACD,IAAI,OAAO,OAAO,KAAK,QAAQ,EAAE,CAAC;QAChC,OAAO,OAAO,CAAC;IACjB,CAAC;IACD,IAAI,KAAK,CAAC,OAAO,CAAC,OAAO,CAAC,EAAE,CAAC;QAC3B,OAAO,IAAA,kCAAkB,EAAC,OAAO,CAAC,CAAC;IACrC,CAAC;IACD,OAAO,IAAI,CAAC,SAAS,CAAC,OAAO,CAAC,CAAC;AACjC,CAAC;AAED,2EAA2E;AAC3E,SAAS,sBAAsB,CAAC,OAAgC;IAC9D,IAAI,OAAO,OAAO,KAAK,QAAQ,EAAE,CAAC;QAChC,OAAO,OAAO,CAAC,CAAC,CAAC,CAAC,EAAE,IAAI,EAAE,MAAM,EAAE,IAAI,EAAE,OAAO,EAAE,CAAC,CAAC,CAAC,CAAC,EAAE,CAAC;IAC1D,CAAC;IACD,IAAI,KAAK,CAAC,OAAO,CAAC,OAAO,CAAC,EAAE,CAAC;QAC3B,OAAO,OAAO,CAAC;IACjB,CAAC;IACD,OAAO,EAAE,CAAC;AACZ,CAAC;AAED,0DAA0D;AAC1D,SAAS,qBAAqB,CAAC,OAA0B;IACvD,KAAK,MAAM,KAAK,IAAI,OAAO,EAAE,CAAC;QAC5B,MAAM,EAAE,GAAG,IAAA,kCAAkB,EAAC,KAAK,CAAC,SAAS,CAAC,CAAC;QAC/C,IAAI,EAAE,IAAI,IAAI,EAAE,CAAC;YACf,OAAO,EAAE,CAAC;QACZ,CAAC;IACH,CAAC;IACD,OAAO,IAAI,CAAC;AACd,CAAC;AAED,yDAAyD;AACzD,SAAS,oBAAoB,CAAC,OAA0B;IACtD,KAAK,IAAI,CAAC,GAAG,OAAO,CAAC,MAAM,GAAG,CAAC,EAAE,CAAC,IAAI,CAAC,EAAE,CAAC,EAAE,EAAE,CAAC;QAC7C,MAAM,EAAE,GAAG,IAAA,kCAAkB,EAAC,OAAO,CAAC,CAAC,CAAC,CAAC,SAAS,CAAC,CAAC;QACpD,IAAI,EAAE,IAAI,IAAI,EAAE,CAAC;YACf,OAAO,EAAE,CAAC;QACZ,CAAC;IACH,CAAC;IACD,OAAO,IAAI,CAAC;AACd,CAAC;AAED,+DAA+D;AAC/D,SAAS,YAAY,CAAC,OAA0B;IAC9C,KAAK,MAAM,KAAK,IAAI,OAAO,EAAE,CAAC;QAC5B,IAAI,KAAK,CAAC,OAAO,IAAI,IAAI,EAAE,CAAC;YAC1B,OAAO,KAAK,CAAC,OAAO,CAAC;QACvB,CAAC;IACH,CAAC;IACD,OAAO,IAAI,CAAC;AACd,CAAC;AAED,0EAA0E;AAC1E,SAAS,uBAAuB,CAAC,OAA0B;IACzD,KAAK,MAAM,KAAK,IAAI,OAAO,EAAE,CAAC;QAC5B,IAAI,KAAK,CAAC,IAAI,KAAK,MAAM,IAAI,KAAK,CAAC,cAAc,IAAI,IAAI,EAAE,CAAC;YAC1D,OAAO,KAAK,CAAC,cAAc,CAAC;QAC9B,CAAC;IACH,CAAC;IACD,OAAO,IAAI,CAAC;AACd,CAAC","names":[],"sources":["/workspace/repo/libs/typescript/integrations/claude-code/src/tracing.ts"],"sourcesContent":["/**\n * MLflow tracing integration for Claude Code.\n *\n * Reads a Claude Code JSONL transcript and emits a single MLflow trace shaped\n * like the other CLI-agent integrations:\n *\n *   AGENT claude_code_conversation\n *   ├─ LLM  llm_call          (one per assistant turn; Anthropic message format)\n *   ├─ TOOL tool_<Name>       (one per tool_use; paired with its tool_result)\n *   └─ TOOL tool_Task\n *      └─ AGENT subagent_<type>   (sub-agent activity, inline or from a file)\n *         ├─ LLM  llm_call\n *         └─ TOOL tool_<Name>\n *\n * Claude Code specifics:\n * - Assistant turns carry `text` and `tool_use` blocks in a single content\n *   array; token usage lives on `message.usage`.\n * - Tool results come back as `user` entries whose content is an array of\n *   `tool_result` blocks, matched to the `tool_use` by `tool_use_id`.\n * - `Task` tool calls spawn sub-agents. Their activity is delivered either\n *   inline as `progress` entries (`data.message` per event) or written to a\n *   separate `subagents/agent-<agentId>.jsonl` file.\n */\n\nimport { existsSync } from 'node:fs';\nimport { basename, dirname, join } from 'node:path';\n\nimport {\n  startSpan,\n  flushTraces,\n  InMemoryTraceManager,\n  SpanStatusCode,\n  SpanType,\n  SpanAttributeKey,\n  TokenUsageKey,\n  type LiveSpan,\n} from '@mlflow/core';\n\nimport type { ContentBlock, TranscriptEntry } from './types.js';\nimport {\n  extractTextContent,\n  findFinalAssistantResponse,\n  findFirstUserMessageIndex,\n  findLastUserMessageIndex,\n  isToolResultCarrier,\n  parseTimestampToNs,\n  readTranscript,\n} from './transcript.js';\n\nconst MESSAGE_FORMAT_ANTHROPIC = 'anthropic';\nconst TASK_TOOL_NAME = 'Task';\nconst TOOL_REJECTED_MESSAGE = \"The user doesn't want to proceed with this tool use.\";\n\n/** Anthropic-format message accumulated as LLM span input. */\ninterface AnthropicMessage {\n  role: string;\n  content: string | ContentBlock[];\n}\n\n/** Resolved tool result for a given `tool_use_id`. */\ninterface ToolResultInfo {\n  content: string;\n  isError: boolean;\n  timestampNs: number | null;\n  agentId?: string;\n}\n\n/** Filesystem context used to locate separate sub-agent transcripts. */\ninterface Ctx {\n  transcriptDir: string;\n  transcriptBase: string;\n}\n\n/**\n * Read a Claude Code JSONL transcript and convert it into an MLflow trace.\n *\n * Missing files, empty transcripts, and transcripts with no \"real\" user\n * messages are handled gracefully by creating no spans.\n */\nexport async function processTranscript(filePath: string, sessionId: string): Promise<void> {\n  let entries: TranscriptEntry[];\n  try {\n    entries = readTranscript(filePath);\n  } catch {\n    return;\n  }\n\n  if (entries.length === 0) {\n    return;\n  }\n\n  const lastUserIdx = findLastUserMessageIndex(entries);\n  if (lastUserIdx === null) {\n    return;\n  }\n\n  const firstUserIdx = findFirstUserMessageIndex(entries) ?? lastUserIdx;\n  const prompt = extractTextContent(entries[firstUserIdx].message?.content ?? '');\n  const finalResponse = findFinalAssistantResponse(entries, lastUserIdx) ?? '';\n\n  const version = firstVersion(entries);\n  const permissionMode = firstUserPermissionMode(entries);\n\n  const ctx: Ctx = {\n    transcriptDir: dirname(filePath),\n    transcriptBase: basename(filePath, '.jsonl'),\n  };\n\n  const startNs = firstEntryTimestampNs(entries);\n  const endNs = lastEntryTimestampNs(entries);\n\n  const rootSpan = startSpan({\n    name: 'claude_code_conversation',\n    spanType: SpanType.AGENT,\n    inputs: { prompt },\n    ...(startNs != null ? { startTimeNs: startNs } : {}),\n  });\n\n  buildConversationSpans(rootSpan, entries, ctx);\n\n  // Attach trace metadata + previews directly through the trace manager;\n  // updateCurrentTrace() needs an active OTel context which hook-based\n  // integrations don't have (same pattern as codex/qwen-code).\n  const traceId = rootSpan.traceId;\n  if (traceId) {\n    const trace = InMemoryTraceManager.getInstance().getTrace(traceId);\n    if (trace) {\n      trace.info.traceMetadata = {\n        ...trace.info.traceMetadata,\n        'mlflow.trace.session': sessionId,\n        'mlflow.trace.user': process.env.USER ?? '',\n        'mlflow.trace.working_directory': process.cwd(),\n        ...(permissionMode != null ? { 'mlflow.trace.permission_mode': permissionMode } : {}),\n        ...(version != null ? { 'mlflow.claude_code_version': version } : {}),\n      };\n      trace.info.requestPreview = prompt;\n      trace.info.responsePreview = finalResponse;\n    }\n  }\n\n  rootSpan.end({\n    outputs: { status: 'completed', response: finalResponse },\n    ...(endNs != null ? { endTimeNs: endNs } : {}),\n  });\n\n  await flushTraces();\n}\n\n/**\n * Walk a conversation (the main transcript, or a sub-agent's entries) and\n * create LLM/TOOL child spans under `parentSpan`, reconstructing the running\n * Anthropic-format message history as it goes.\n */\nfunction buildConversationSpans(parentSpan: LiveSpan, entries: TranscriptEntry[], ctx: Ctx): void {\n  const toolResults = buildToolResultMap(entries);\n  const progressByParent = groupProgressByParent(entries);\n  const messages: AnthropicMessage[] = [];\n  let prevBoundaryNs = firstEntryTimestampNs(entries);\n\n  for (const entry of entries) {\n    const tsNs = parseTimestampToNs(entry.timestamp);\n\n    if (entry.type === 'queue-operation') {\n      // Only `enqueue` operations represent user-authored content that the\n      // model subsequently sees; other queue mutations are bookkeeping.\n      if (entry.operation === 'enqueue') {\n        messages.push({ role: 'user', content: entry.content ?? '' });\n      }\n      continue;\n    }\n\n    if (entry.type === 'progress') {\n      // Consumed via `progressByParent` when the parent Task span is built.\n      continue;\n    }\n\n    if (entry.type === 'user') {\n      if (!entry.message) {\n        continue;\n      }\n      const content = entry.message.content;\n\n      if (isToolResultCarrier(entry)) {\n        messages.push({ role: 'user', content });\n        if (tsNs != null) {\n          prevBoundaryNs = tsNs;\n        }\n        continue;\n      }\n\n      if (entry.isCompactSummary === true) {\n        continue;\n      }\n      if (extractTextContent(content).startsWith('Base directory:')) {\n        continue;\n      }\n\n      messages.push({ role: 'user', content });\n      if (tsNs != null) {\n        prevBoundaryNs = tsNs;\n      }\n      continue;\n    }\n\n    if (entry.type === 'assistant') {\n      if (!entry.message) {\n        continue;\n      }\n      const blocks = normalizeContentBlocks(entry.message.content);\n      if (blocks.length === 0) {\n        continue;\n      }\n\n      createLlmSpan(parentSpan, entry, blocks, [...messages], prevBoundaryNs, tsNs);\n\n      for (const block of blocks) {\n        if (block.type === 'tool_use') {\n          createToolSpan(parentSpan, block, tsNs, toolResults, progressByParent, ctx);\n        }\n      }\n\n      messages.push({ role: 'assistant', content: blocks });\n      if (tsNs != null) {\n        prevBoundaryNs = tsNs;\n      }\n    }\n  }\n}\n\n/** Create the LLM span for a single assistant turn. */\nfunction createLlmSpan(\n  parentSpan: LiveSpan,\n  entry: TranscriptEntry,\n  blocks: ContentBlock[],\n  messages: AnthropicMessage[],\n  startNs: number | null,\n  endNs: number | null,\n): void {\n  const model = entry.message?.model;\n\n  const llmSpan = startSpan({\n    name: 'llm_call',\n    parent: parentSpan,\n    spanType: SpanType.LLM,\n    inputs: { ...(model ? { model } : {}), messages },\n    attributes: { ...(model ? { model } : {}) },\n    ...(startNs != null ? { startTimeNs: startNs } : {}),\n  });\n\n  llmSpan.setAttribute(SpanAttributeKey.MESSAGE_FORMAT, MESSAGE_FORMAT_ANTHROPIC);\n\n  const usage = entry.message?.usage;\n  if (usage) {\n    const inputTokens = (usage.input_tokens ?? 0) + (usage.cache_creation_input_tokens ?? 0);\n    const outputTokens = usage.output_tokens ?? 0;\n    llmSpan.setAttribute(SpanAttributeKey.TOKEN_USAGE, {\n      [TokenUsageKey.INPUT_TOKENS]: inputTokens,\n      [TokenUsageKey.OUTPUT_TOKENS]: outputTokens,\n      [TokenUsageKey.TOTAL_TOKENS]: inputTokens + outputTokens,\n    });\n  }\n\n  llmSpan.end({\n    outputs: { type: 'message', role: 'assistant', content: blocks },\n    ...(endNs != null ? { endTimeNs: endNs } : {}),\n  });\n}\n\n/** Create a TOOL span for a single `tool_use` block. */\nfunction createToolSpan(\n  parentSpan: LiveSpan,\n  block: ContentBlock,\n  callTsNs: number | null,\n  toolResults: Map<string, ToolResultInfo>,\n  progressByParent: Map<string, TranscriptEntry[]>,\n  ctx: Ctx,\n): void {\n  const toolId = block.id ?? '';\n  const result = toolResults.get(toolId);\n\n  const toolSpan = startSpan({\n    name: `tool_${block.name}`,\n    parent: parentSpan,\n    spanType: SpanType.TOOL,\n    inputs: block.input ?? {},\n    attributes: { tool_name: block.name, tool_id: toolId },\n    ...(callTsNs != null ? { startTimeNs: callTsNs } : {}),\n  });\n\n  if (result?.isError) {\n    const message = result.content.trim() ? result.content : TOOL_REJECTED_MESSAGE;\n    toolSpan.recordException(new Error(message));\n    toolSpan.setStatus(SpanStatusCode.ERROR, message);\n  }\n\n  if (block.name === TASK_TOOL_NAME) {\n    buildSubAgentSpan(toolSpan, block, result, progressByParent, ctx);\n  }\n\n  const endNs = result?.timestampNs ?? callTsNs;\n  toolSpan.end({\n    outputs: { result: result?.content ?? '' },\n    ...(endNs != null ? { endTimeNs: endNs } : {}),\n  });\n}\n\n/**\n * Build the nested `subagent_<type>` AGENT span for a `Task` tool call.\n * Sub-agent activity is sourced from inline `progress` entries when present,\n * otherwise from a separate `subagents/agent-<agentId>.jsonl` file.\n */\nfunction buildSubAgentSpan(\n  toolSpan: LiveSpan,\n  taskBlock: ContentBlock,\n  taskResult: ToolResultInfo | undefined,\n  progressByParent: Map<string, TranscriptEntry[]>,\n  ctx: Ctx,\n): void {\n  const subagentType = (taskBlock.input?.subagent_type as string | undefined) ?? 'unknown';\n\n  const progress = progressByParent.get(taskBlock.id ?? '') ?? [];\n  if (progress.length > 0) {\n    const subEntries = progress\n      .map((p) => p.data?.message)\n      .filter((m): m is TranscriptEntry => m != null);\n    const startNs = parseTimestampToNs(progress[0].timestamp) ?? firstEntryTimestampNs(subEntries);\n    const endNs =\n      taskResult?.timestampNs ??\n      parseTimestampToNs(progress[progress.length - 1].timestamp) ??\n      lastEntryTimestampNs(subEntries);\n    createSubAgentSpan(toolSpan, subagentType, taskBlock, taskResult, subEntries, ctx, startNs, endNs);\n    return;\n  }\n\n  const agentId = taskResult?.agentId;\n  if (!agentId) {\n    return;\n  }\n  const file = join(ctx.transcriptDir, ctx.transcriptBase, 'subagents', `agent-${agentId}.jsonl`);\n  if (!existsSync(file)) {\n    return;\n  }\n  let subEntries: TranscriptEntry[] = [];\n  try {\n    subEntries = readTranscript(file);\n  } catch {\n    return;\n  }\n  const startNs = firstEntryTimestampNs(subEntries);\n  const endNs = taskResult?.timestampNs ?? lastEntryTimestampNs(subEntries);\n  createSubAgentSpan(toolSpan, subagentType, taskBlock, taskResult, subEntries, ctx, startNs, endNs);\n}\n\n/** Create the `subagent_<type>` span and recurse into its conversation. */\nfunction createSubAgentSpan(\n  toolSpan: LiveSpan,\n  subagentType: string,\n  taskBlock: ContentBlock,\n  taskResult: ToolResultInfo | undefined,\n  subEntries: TranscriptEntry[],\n  ctx: