eset() { spanCounter = 0; Object.keys(mockSpans).forEach(k => delete mockSpans[k]); mockTraceInfo.traceMetadata = {}; mockTraceInfo.requestPreview = undefined; mockTraceInfo.responsePreview = undefined; jest.clearAllMocks(); }\n\nbeforeAll(() => { rmSync(DIR, { recursive: true, force: true }); mkdirSync(DIR, { recursive: true }); });\nbeforeEach(reset);\n\nfunction write(name: string, lines: any[]) { const p = join(DIR, name); writeFileSync(p, lines.map(l => JSON.stringify(l)).join('\\n') + '\\n'); return p; }\n\ndescribe('pure helpers', () => {\n  it('parseTimestampToNs', () => {\n    expect(parseTimestampToNs(null)).toBeNull();\n    expect(parseTimestampToNs(undefined)).toBeNull();\n    expect(parseTimestampToNs('')).toBeNull();\n    expect(parseTimestampToNs('not-a-date')).toBeNull();\n    expect(parseTimestampToNs('2026-04-05T10:00:00Z')).toBe(new Date('2026-04-05T10:00:00Z').getTime() * 1e6);\n    expect(parseTimestampToNs(1.7e13)).toBe(Math.floor(1.7e13));\n    expect(parseTimestampToNs(1.7e12)).toBe(Math.floor(1.7e12 * 1e6));\n    expect(parseTimestampToNs(1700)).toBe(Math.floor(1700 * 1e9));\n  });\n  it('extractTextContent', () => {\n    expect(extractTextContent('hi')).toBe('hi');\n    expect(extractTextContent([])).toBe('');\n    expect(extractTextContent([{ type: 'text', text: 'a' }, { type: 'tool_use' } as any, { type: 'text', text: 'b' }])).toBe('a\\nb');\n  });\n  it('findLastUserMessageIndex / findFinalAssistantResponse', () => {\n    const entries: any[] = [\n      { type: 'user', message: { role: 'user', content: 'hello' } },\n      { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'hi there' }] } },\n      { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 'x', content: 'r' }] } },\n      { type: 'user', message: { role: 'user', content: 'Base directory: /x' } },\n      { type: 'user', isCompactSummary: true, message: { role: 'user', content: 'summary' } },\n    ];\n    expect(findLastUserMessageIndex(entries)).toBe(0);\n    expect(findLastUserMessageIndex([])).toBeNull();\n    expect(findFinalAssistantResponse(entries, 0)).toBe('hi there');\n  });\n});\n\ndescribe('processTranscript basic', () => {\n  it('creates root + llm spans, previews, metadata, flush', async () => {\n    const p = write('basic.jsonl', [\n      { type: 'user', message: { role: 'user', content: 'what is 2+2' }, timestamp: '2026-04-05T10:00:00Z', version: '1.2.3', permissionMode: 'default', sessionId: 's' },\n      { type: 'assistant', message: { role: 'assistant', model: 'claude-x', content: [{ type: 'text', text: '4' }], usage: { input_tokens: 100, output_tokens: 10, cache_creation_input_tokens: 5, cache_read_input_tokens: 50 } }, timestamp: '2026-04-05T10:00:02Z' },\n    ]);\n    await processTranscript(p, 'sess-1');\n    const r = root();\n    expect(r.name).toBe('claude_code_conversation');\n    expect(r.spanType).toBe('AGENT');\n    expect(r.inputs).toEqual({ prompt: 'what is 2+2' });\n    const endCall = (r.end as jest.Mock).mock.calls[0][0];\n    expect(endCall.outputs).toEqual({ status: 'completed', response: '4' });\n    const llm = byType('LLM');\n    expect(llm.length).toBe(1);\n    expect(llm[0].parentId).toBe(r.spanId);\n    expect(llm[0].attributes['mlflow.message.format']).toBe('anthropic');\n    const llmEnd = (llm[0].end as jest.Mock).mock.calls[0][0];\n    expect(llmEnd.outputs).toEqual({ type: 'message', role: 'assistant', content: [{ type: 'text', text: '4' }] });\n    expect(llm[0].setAttribute).toHaveBeenCalledWith('mlflow.chat.tokenUsage', { input_tokens: 105, output_tokens: 10, total_tokens: 115 });\n    expect(mockTraceInfo.traceMetadata['mlflow.trace.session']).toBe('sess-1');\n    expect(mockTraceInfo.traceMetadata['mlflow.trace.working_directory']).toBe(process.cwd());\n    expect(mockTraceInfo.traceMetadata['mlflow.trace.permission_mode']).toBe('default');\n    expect(mockTraceInfo.traceMetadata['mlflow.claude_code_version']).toBe('1.2.3');\n    expect(mockTraceInfo.requestPreview).toBe('what is 2+2');\n    expect(mockTraceInfo.responsePreview).toBe('4');\n    expect(flushTraces).toHaveBeenCalled();\n  });\n\n  it('no spans for empty/missing/no-user', async () => {\n    write('empty.jsonl', []);\n    await processTranscript(join(DIR, 'empty.jsonl'), 's'); expect(spans().length).toBe(0);\n    reset();\n    await processTranscript(join(DIR, 'does-not-exist.jsonl'), 's'); expect(spans().length).toBe(0);\n    reset();\n    write('nouser.jsonl', [{ type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'hi' }] } }]);\n    await processTranscript(join(DIR, 'nouser.jsonl'), 's'); expect(spans().length).toBe(0);\n    expect(flushTraces).not.toHaveBeenCalled();\n  });\n});\n\ndescribe('tools', () => {\n  it('tool span + result + enqueue in messages', async () => {\n    const p = write('tool.jsonl', [\n      { type: 'user', message: { role: 'user', content: 'list files' }, timestamp: '2026-04-05T10:00:00Z' },\n      { type: 'assistant', message: { role: 'assistant', content: [{ type: 'tool_use', id: 'toolu_1', name: 'Bash', input: { command: 'ls' } }] }, timestamp: '2026-04-05T10:00:02Z' },\n      { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 'toolu_1', content: 'a.txt\\nb.txt' }] }, timestamp: '2026-04-05T10:00:03Z' },\n      { type: 'queue-operation', operation: 'enqueue', content: 'also show hidden', timestamp: '2026-04-05T10:00:04Z' },\n      { type: 'queue-operation', operation: 'remove', content: 'ignored', timestamp: '2026-04-05T10:00:04Z' },\n      { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'done' }] }, timestamp: '2026-04-05T10:00:05Z' },\n    ]);\n    await processTranscript(p, 's');\n    const tool = byType('TOOL');\n    expect(tool.length).toBe(1);\n    expect(tool[0].name).toBe('tool_Bash');\n    expect(tool[0].attributes.tool_name).toBe('Bash');\n    expect(tool[0].attributes.tool_id).toBe('toolu_1');\n    expect(tool[0].inputs).toEqual({ command: 'ls' });\n    const te = (tool[0].end as jest.Mock).mock.calls[0][0];\n    expect(te.outputs).toEqual({ result: 'a.txt\\nb.txt' });\n    expect(tool[0].startTimeNs).toBe(parseTimestampToNs('2026-04-05T10:00:02Z'));\n    expect(tool[0].endTimeNs).toBe(parseTimestampToNs('2026-04-05T10:00:03Z'));\n    const llm = byType('LLM');\n    expect(llm.length).toBe(2);\n    const secondMsgs = llm[1].inputs.messages;\n    expect(secondMsgs).toContainEqual({ role: 'user', content: 'also show hidden' });\n    expect(secondMsgs.find((m: any) => Array.isArray(m.content) && m.content[0]?.type === 'tool_result')).toBeTruthy();\n    expect(secondMsgs.find((m: any) => JSON.stringify(m.content).includes('ignored'))).toBeFalsy();\n  });\n\n  it('records exception on is_error tool', async () => {\n    const p = write('reject.jsonl', [\n      { type: 'user', message: { role: 'user', content: 'rm everything' }, timestamp: '2026-04-05T10:00:00Z' },\n      { type: 'assistant', message: { role: 'assistant', content: [{ type: 'tool_use', id: 't1', name: 'Bash', input: { command: 'rm -rf /' } }] }, timestamp: '2026-04-05T10:00:01Z' },\n      { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 't1', is_error: true, content: \"The user doesn't want to proceed with this tool use.\" }] }, timestamp: '2026-04-05T10:00:02Z' },\n    ]);\n    await processTranscript(p, 's');\n    const tool = byType('TOOL')[0];\n    expect(tool.recordException).toHaveBeenCalled();\n    expect(tool.exceptions[0].message).toContain(\"doesn't want to proceed\");\n  });\n\n  it('parallel tasks each get own output', async () => {\n    const p = write('parallel.jsonl', [\n      { type: 'user', message: { role: 'user', content: 'do two things' }, timestamp: '2026-04-05T10:00:00Z' },\n      { type: 'assistant', message: { role: 'assistant', content: [\n        { type: 'tool_use', id: 'A', name: 'Task', input: { subagent_type: 'Explore', prompt: 'find x' } },\n        { type: 'tool_use', id: 'B', name: 'Task', input: { subagent_type: 'Plan', prompt: 'find y' } },\n      ] }, timestamp: '2026-04-05T10:00:01Z' },\n      { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 'A', content: 'result A' }] }, timestamp: '2026-04-05T10:00:02Z' },\n      { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 'B', content: 'result B' }] }, timestamp: '2026-04-05T10:00:03Z' },\n      { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'both done' }] }, timestamp: '2026-04-05T10:00:04Z' },\n    ]);\n    await processTranscript(p, 's');\n    const tasks = byType('TOOL').filter((t: any) => t.name === 'tool_Task');\n    expect(tasks.length).toBe(2);\n    const outs = tasks.map((t: any) => (t.end as jest.Mock).mock.calls[0][0].outputs.result).sort();\n    expect(outs).toEqual(['result A', 'result B']);\n  });\n});\n\ndescribe('subagents', () => {\n  it('inline progress subagent', async () => {\n    const p = write('sub-inline.jsonl', [\n      { type: 'user', message: { role: 'user', content: 'explore' }, timestamp: '2026-04-05T10:00:00Z' },\n      { type: 'assistant', message: { role: 'assistant', content: [{ type: 'tool_use', id: 'T1', name: 'Task', input: { subagent_type: 'Explore', prompt: 'look around' } }] }, timestamp: '2026-04-05T10:00:01Z' },\n      { type: 'progress', parentToolUseID: 'T1', toolUseID: 'x', timestamp: '2026-04-05T10:00:02Z', data: { type: 'agent', agentId: 'ag1', prompt: 'look around', message: { type: 'assistant', message: { role: 'assistant', content: [{ type: 'tool_use', id: 'S1', name: 'Grep', input: { pattern: 'foo' } }] }, timestamp: '2026-04-05T10:00:02Z' } } },\n      { type: 'progress', parentToolUseID: 'T1', toolUseID: 'x', timestamp: '2026-04-05T10:00:03Z', data: { type: 'agent', agentId: 'ag1', prompt: 'look around', message: { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 'S1', content: 'match' }] }, timestamp: '2026-04-05T10:00:03Z' } } },\n      { type: 'progress', parentToolUseID: 'T1', toolUseID: 'x', timestamp: '2026-04-05T10:00:04Z', data: { type: 'agent', agentId: 'ag1', prompt: 'look around', message: { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'found it' }] }, timestamp: '2026-04-05T10:00:04Z' } } },\n      { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 'T1', content: 'found it' }] }, timestamp: '2026-04-05T10:00:05Z' },\n      { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'ok' }] }, timestamp: '2026-04-05T10:00:06Z' },\n    ]);\n    await processTranscript(p, 's');\n    const sub = spans().find((s: any) => s.name === 'subagent_Explore') as any;\n    expect(sub).toBeTruthy();\n    const taskSpan = byType('TOOL').find((t: any) => t.name === 'tool_Task') as any;\n    expect(sub.parentId).toBe(taskSpan.spanId);\n    // sub children\n    const subChildren = spans().filter((s: any) => s.parentId === sub.spanId);\n    expect(subChildren.some((s: any) => s.spanType === 'LLM')).toBe(true);\n    expect(subChildren.some((s: any) => s.spanType === 'TOOL' && s.name === 'tool_Grep')).toBe(true);\n  });\n\n  it('file-based subagent', async () => {\n    mkdirSync(join(DIR, 'sub-file', 'subagents'), { recursive: true });\n    writeFileSync(join(DIR, 'sub-file', 'subagents', 'agent-XYZ.jsonl'),\n      [\n        { type: 'user', message: { role: 'user', content: 'sub task' }, timestamp: '2026-04-05T10:00:02Z' },\n        { type: 'assistant', message: { role: 'assistant', content: [{ type: 'tool_use', id: 'S9', name: 'Read', input: { file: 'a' } }] }, timestamp: '2026-04-05T10:00:03Z' },\n        { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 'S9', content: 'data' }] }, timestamp: '2026-04-05T10:00:04Z' },\n        { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'sub done' }] }, timestamp: '2026-04-05T10:00:05Z' },\n      ].map(l => JSON.stringify(l)).join('\\n'));\n    const p = write('sub-file.jsonl', [\n      { type: 'user', message: { role: 'user', content: 'delegate' }, timestamp: '2026-04-05T10:00:00Z' },\n      { type: 'assistant', message: { role: 'assistant', content: [{ type: 'tool_use', id: 'T5', name: 'Task', input: { subagent_type: 'general-purpose', prompt: 'go' } }] }, timestamp: '2026-04-05T10:00:01Z' },\n      { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 'T5', content: 'sub done' }] }, toolUseResult: { agentId: 'XYZ', status: 'completed' }, timestamp: '2026-04-05T10:00:06Z' },\n      { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'ok' }] }, timestamp: '2026-04-05T10:00:07Z' },\n    ]);\n    await processTranscript(p, 's');\n    const sub = spans().find((s: any) => s.name === 'subagent_general-purpose') as any;\n    expect(sub).toBeTruthy();\n    const subChildren = spans().filter((s: any) => s.parentId === sub.spanId);\n    expect(subChildren.some((s: any) => s.spanType === 'TOOL' && s.name === 'tool_Read')).toBe(true);\n  });\n});\n"],"version":3}
