,CAAC;IACH,CAAC;IACD,OAAO,IAAI,CAAC;AACd,CAAC;AAED,0EAA0E;AAC1E,SAAS,uBAAuB,CAAC,OAA0B;IACzD,KAAK,MAAM,KAAK,IAAI,OAAO,EAAE,CAAC;QAC5B,IAAI,KAAK,CAAC,IAAI,KAAK,MAAM,IAAI,KAAK,CAAC,cAAc,IAAI,IAAI,EAAE,CAAC;YAC1D,OAAO,KAAK,CAAC,cAAc,CAAC;QAC9B,CAAC;IACH,CAAC;IACD,OAAO,IAAI,CAAC;AACd,CAAC","names":[],"sources":["/workspace/repo/libs/typescript/integrations/claude-code/src/tracing.ts"],"sourcesContent":["/**\n * MLflow tracing integration for Claude Code.\n *\n * Reads a Claude Code JSONL transcript and emits a single MLflow trace shaped\n * like the other CLI-agent integrations:\n *\n *   AGENT claude_code_conversation\n *   ├─ LLM  llm_call          (one per assistant turn; Anthropic message format)\n *   ├─ TOOL tool_<Name>       (one per tool_use; paired with its tool_result)\n *   └─ TOOL tool_Task\n *      └─ AGENT subagent_<type>   (sub-agent activity, inline or from a file)\n *         ├─ LLM  llm_call\n *         └─ TOOL tool_<Name>\n *\n * Claude Code specifics:\n * - Assistant turns carry `text` and `tool_use` blocks in a single content\n *   array; token usage lives on `message.usage`.\n * - Tool results come back as `user` entries whose content is an array of\n *   `tool_result` blocks, matched to the `tool_use` by `tool_use_id`.\n * - `Task` tool calls spawn sub-agents. Their activity is delivered either\n *   inline as `progress` entries (`data.message` per event) or written to a\n *   separate `subagents/agent-<agentId>.jsonl` file.\n */\n\nimport { existsSync } from 'node:fs';\nimport { basename, dirname, join } from 'node:path';\n\nimport {\n  startSpan,\n  flushTraces,\n  InMemoryTraceManager,\n  SpanStatusCode,\n  SpanType,\n  SpanAttributeKey,\n  TokenUsageKey,\n  type LiveSpan,\n} from '@mlflow/core';\n\nimport type { ContentBlock, TranscriptEntry } from './types.js';\nimport {\n  extractTextContent,\n  findFinalAssistantResponse,\n  findFirstUserMessageIndex,\n  findLastUserMessageIndex,\n  isToolResultCarrier,\n  parseTimestampToNs,\n  readTranscript,\n} from './transcript.js';\n\nconst MESSAGE_FORMAT_ANTHROPIC = 'anthropic';\nconst TASK_TOOL_NAME = 'Task';\nconst TOOL_REJECTED_MESSAGE = \"The user doesn't want to proceed with this tool use.\";\n\n/** Anthropic-format message accumulated as LLM span input. */\ninterface AnthropicMessage {\n  role: string;\n  content: string | ContentBlock[];\n}\n\n/** Resolved tool result for a given `tool_use_id`. */\ninterface ToolResultInfo {\n  content: string;\n  isError: boolean;\n  timestampNs: number | null;\n  agentId?: string;\n}\n\n/** Filesystem context used to locate separate sub-agent transcripts. */\ninterface Ctx {\n  transcriptDir: string;\n  transcriptBase: string;\n}\n\n/**\n * Read a Claude Code JSONL transcript and convert it into an MLflow trace.\n *\n * Missing files, empty transcripts, and transcripts with no \"real\" user\n * messages are handled gracefully by creating no spans.\n */\nexport async function processTranscript(filePath: string, sessionId: string): Promise<void> {\n  let entries: TranscriptEntry[];\n  try {\n    entries = readTranscript(filePath);\n  } catch {\n    return;\n  }\n\n  if (entries.length === 0) {\n    return;\n  }\n\n  const lastUserIdx = findLastUserMessageIndex(entries);\n  if (lastUserIdx == null) {\n    return;\n  }\n\n  const firstUserIdx = findFirstUserMessageIndex(entries) ?? lastUserIdx;\n  const prompt = extractTextContent(entries[firstUserIdx].message?.content ?? '');\n  const finalResponse = findFinalAssistantResponse(entries, lastUserIdx) ?? '';\n\n  const version = firstVersion(entries);\n  const permissionMode = firstUserPermissionMode(entries);\n\n  const ctx: Ctx = {\n    transcriptDir: dirname(filePath),\n    transcriptBase: basename(filePath, '.jsonl'),\n  };\n\n  const startNs = firstEntryTimestampNs(entries);\n  const endNs = lastEntryTimestampNs(entries);\n\n  const rootSpan = startSpan({\n    name: 'claude_code_conversation',\n    spanType: SpanType.AGENT,\n    inputs: { prompt },\n    ...(startNs != null ? { startTimeNs: startNs } : {}),\n  });\n\n  buildConversationSpans(rootSpan, entries, ctx);\n\n  // Attach trace metadata + previews directly through the trace manager;\n  // updateCurrentTrace() needs an active OTel context which hook-based\n  // integrations don't have (same pattern as codex/qwen-code).\n  const traceId = rootSpan.traceId;\n  if (traceId) {\n    const trace = InMemoryTraceManager.getInstance().getTrace(traceId);\n    if (trace) {\n      trace.info.traceMetadata = {\n        ...trace.info.traceMetadata,\n        'mlflow.trace.session': sessionId,\n        'mlflow.trace.user': process.env.USER ?? '',\n        'mlflow.trace.working_directory': process.cwd(),\n        ...(permissionMode != null ? { 'mlflow.trace.permission_mode': permissionMode } : {}),\n        ...(version != null ? { 'mlflow.claude_code_version': version } : {}),\n      };\n      trace.info.requestPreview = prompt;\n      trace.info.responsePreview = finalResponse;\n    }\n  }\n\n  rootSpan.end({\n    outputs: { status: 'completed', response: finalResponse },\n    ...(endNs != null ? { endTimeNs: endNs } : {}),\n  });\n\n  await flushTraces();\n}\n\n/**\n * Walk a conversation (the main transcript, or a sub-agent's entries) and\n * create LLM/TOOL child spans under `parentSpan`, reconstructing the running\n * Anthropic-format message history as it goes.\n */\nfunction buildConversationSpans(parentSpan: LiveSpan, entries: TranscriptEntry[], ctx: Ctx): void {\n  const toolResults = buildToolResultMap(entries);\n  const progressByParent = groupProgressByParent(entries);\n  const messages: AnthropicMessage[] = [];\n  let prevBoundaryNs = firstEntryTimestampNs(entries);\n\n  for (const entry of entries) {\n    const tsNs = parseTimestampToNs(entry.timestamp);\n\n    if (entry.type === 'queue-operation') {\n      // Only `enqueue` operations represent user-authored content that the\n      // model subsequently sees; other queue mutations are bookkeeping.\n      if (entry.operation =