taskBlock: ContentBlock,\n  taskResult: ToolResultInfo | undefined,\n  subEntries: TranscriptEntry[],\n  ctx: Ctx,\n  startNs: number | null,\n  endNs: number | null,\n): void {\n  const subSpan = startSpan({\n    name: `subagent_${subagentType}`,\n    parent: toolSpan,\n    spanType: SpanType.AGENT,\n    inputs: { prompt: (taskBlock.input?.prompt as string | undefined) ?? '' },\n    attributes: { subagent_type: subagentType },\n    ...(startNs != null ? { startTimeNs: startNs } : {}),\n  });\n\n  buildConversationSpans(subSpan, subEntries, ctx);\n\n  const response = taskResult?.content || (findFinalAssistantResponse(subEntries, 0) ?? '');\n  subSpan.end({\n    outputs: { response },\n    ...(endNs != null ? { endTimeNs: endNs } : {}),\n  });\n}\n\n/** Map each `tool_use_id` to its resolved tool result. */\nfunction buildToolResultMap(entries: TranscriptEntry[]): Map<string, ToolResultInfo> {\n  const map = new Map<string, ToolResultInfo>();\n  for (const entry of entries) {\n    if (entry.type !== 'user' || !entry.message) {\n      continue;\n    }\n    const content = entry.message.content;\n    if (!Array.isArray(content)) {\n      continue;\n    }\n    const tsNs = parseTimestampToNs(entry.timestamp);\n    for (const block of content) {\n      if (block.type === 'tool_result' && block.tool_use_id) {\n        map.set(block.tool_use_id, {\n          content: getToolResultContent(block.content),\n          isError: block.is_error === true,\n          timestampNs: tsNs,\n          agentId: entry.toolUseResult?.agentId,\n        });\n      }\n    }\n  }\n  return map;\n}\n\n/** Group `progress` entries by their parent tool-use id. */\nfunction groupProgressByParent(entries: TranscriptEntry[]): Map<string, TranscriptEntry[]> {\n  const map = new Map<string, TranscriptEntry[]>();\n  for (const entry of entries) {\n    if (entry.type === 'progress' && entry.parentToolUseID) {\n      const list = map.get(entry.parentToolUseID);\n      if (list) {\n        list.push(entr